mapper.sql:
FROM tb_show s
INNER JOIN tb_performance p ON p.id = s.performance_id
INNER JOIN tb_venue v ON v.id = s.venue_id
WHERE 1 = 1


    AND v.city = #{city}


    AND p.type = #{type}


    AND s.venue_id = #{venueId}


    AND p.artist_id = #{artistId}


    AND DATE(s.start_time) = #{date}

mapper.select:
SELECT DISTINCT p.type FROM tb_show s INNER JOIN tb_performance p ON p.id = s.performance_id INNER JOIN tb_venue v ON v.id = s.venue_id WHERE p.type IS NOT NULL AND TRIM(p.type) != ''
AND v.city = #{city}
ORDER BY p.type
